import SwiftUI

struct SimpleCityList: View {
    let cities: [String] = ["Paris", "Tokyo"]
    var body: some View {
        List(cities, id: \.self) { city in
            Text(city)
        }
    }
}

let cityList = SimpleCityList()
print("SimpleCityList created: \(type(of: cityList))")

import SwiftUI

struct DeletableItemList: View {
    @State private var items = ["A", "B"]
    var body: some View {
        List {
            ForEach(items, id: \.self) { item in
                Text(item)
            }
            .onDelete { offsets in
                items.remove(atOffsets: offsets)
            }
        }
    }
}

let deletable = DeletableItemList()
print("DeletableItemList created: \(type(of: deletable))")
